export const fetchPosts = async (page = 1, limit = 9) = {
	// 1. Одновременная загрузка постов и комментариев
	const [posts, comments] = await Promise.all([getPosts(), getComments()]);

	// 2. Добавляем каждому посту количество комментариев
	const allPosts = posts.map((post) = ({
		...post,
		commentsCount: getCommentsCount(comments, post.id),
	}));

	// 3. Вычисляем границы текущей страницы
	const startIndex = (page - 1) * limit; // с какого индекса начинать
	const endIndex = startIndex + limit;   // до какого индекса брать

	// 4. Отрезаем только нужные посты для текущей страницы
	const paginatedPosts = allPosts.slice(startIndex, endIndex);

	// 5. Возвращаем посты и общее количество страниц
	return {
		error: null,
		res: paginatedPosts,           // посты для текущей страницы
		totalPages: Math.ceil(allPosts.length / limit), // всего страниц
	};
};

